        'governance' => ['title' => 'المجالس واللجان', 'roles' => ['admin', 'risk_manager', 'compliance_officer', 'exec_viewer', 'auditor'], 'link' => '/governance', 'summary' => 'من يجلس في كل مجلس أو لجنة، ومتى انعقدت، ومن حضر، وهل تلتزم بقواعدها.',
            'steps' => ['أنشئ المجلس أو اللجنة مع نوعها والحد الأدنى للاجتماعات سنوياً والنصاب.', 'أضف الأعضاء وعيّن رئيساً واحداً. لا يمكن جدولة اجتماع بلا رئيس.', 'جدول الاجتماع مع جدول أعماله. بعد انعقاده علّم من حضر واكتب المحضر.', 'يفحص النظام النصاب. الاجتماع بلا نصاب يُعلَّم لأن قراراته قد لا تكون صحيحة.', 'يعرض تقرير الالتزام للسنة الاجتماعات المنعقدة مقابل الحد الأدنى وإخفاقات النصاب ومتوسط الحضور.'],
            'tips' => ['سجّل القرارات من «قرارات اللجان» بنفس نوع اللجنة وتاريخ الاجتماع فتظهر في صفحة الاجتماع.', 'المديرون فقط يغيّرون العضوية أو يسجلون الاجتماعات.']],
        'import' => ['title' => 'استيراد البيانات من CSV', 'roles' => ['admin', 'risk_manager', 'compliance_officer', 'dept_manager'], 'link' => '/import', 'summary' => 'حمّل عدداً كبيراً من المخاطر أو قراءات المؤشرات أو التزامات الامتثال دفعة واحدة من جدول.',
            'steps' => ['نزّل قالب ما تريد تحميله واملأه في Excel. أبقِ الصف الأول كما هو.', 'استخدم رموزاً وأسماء مستخدمين موجودة مسبقاً (الإدارة والفئة والمؤشر والمالك).', 'احفظه بصيغة CSV (UTF-8) وارفعه. تفحص المنصة كل صف وتعرض المشاكل حسب السطر.', 'إن كان الملف سليماً راجع العيّنة واضغط «استيراد». إن وُجدت مشكلة في صف واحد فلا يُحفظ شيء.'],
            'tips' => ['صحّح الملف وارفعه من جديد: لا يوجد استيراد جزئي.', 'مدير الإدارة يستورد إلى إدارته فقط.']],
        'recon' => ['title' => 'مطابقة الخسائر', 'roles' => ['admin', 'risk_manager', 'compliance_officer', 'exec_viewer', 'auditor'], 'link' => '/incidents/reconciliation', 'summary' => 'تحقق من أن خسائر سجل الحوادث تتفق مع قيود الخسائر التشغيلية في الأستاذ العام.',
            'steps' => ['تعطيك المالية قيود الخسائر التشغيلية الشهرية بصيغة CSV (الفترة والحساب والمبلغ والوصف).', 'حمّلها من «استيراد البيانات» واختر «قيود خسائر الأستاذ العام». الشهر المحمّل سابقاً يُرفض.', 'افتح صفحة المطابقة: يعرض كل شهر صافي خسائر الحوادث ومجموع الأستاذ والفرق.', 'اضغط مبلغ الحوادث لترى الحوادث وراءه. الفرق غير المفسَّر يعني حادثاً غير مسجل أو قيداً خاطئاً في الأستاذ.'],
            'tips' => ['يمكن للمدير ضبط هامش مقبول من الإعدادات.', 'أزل الشهر وأعد تحميله إن صُحّحت أرقام الأستاذ.']],
        'strategy' => ['title' => 'الأهداف الاستراتيجية', 'roles' => ['admin', 'risk_manager', 'compliance_officer', 'exec_viewer', 'auditor'], 'link' => '/strategy', 'summary' => 'أهداف المصرف على بطاقة أداء متوازن، مع التقدم والمخاطر التي تهدد كل هدف.',
            'steps' => ['أضف الهدف مع منظوره (المالي أو العملاء أو العمليات الداخلية أو التعلّم) ومسؤوله ووحدته وقيمته الابتدائية والمستهدف وتاريخ الاستحقاق.', 'سجّل التقدم دورياً. تُحسب النسبة من القيمة الابتدائية إلى المستهدف وتُلوَّن أخضر (90% فأكثر) أو أصفر (60–89%) أو أحمر (أقل من 60%).', 'اربط المخاطر من السجل التي قد توقف الهدف. يتبين بذلك أي الأهداف معرّض.', 'تجمع صفحة البطاقة كل الأهداف حسب المنظور وتُطبع بشكل مناسب للمجلس.'],
            'tips' => ['للأهداف التي يكون الأقل فيها أفضل (التكلفة والحوادث) اختر «الأقل أفضل»: عندها يجب أن يكون المستهدف أقل من القيمة الابتدائية.', 'الأهداف التي تجاوزت موعدها تظهر بتحذير حتى تبلغ 100%.']],
        'ia' => ['title' => 'التدقيق الداخلي', 'roles' => ['admin', 'risk_manager', 'compliance_officer', 'exec_viewer', 'auditor'], 'link' => '/ia', 'summary' => 'خطة تدقيق سنوية مبنية على المخاطر، ومهام بأوراق عمل، وملاحظات تُتابَع حتى إغلاقها.',
            'steps' => ['سجّل ما يمكن تدقيقه في نطاق التدقيق، وقيّم الأهمية المالية والتعرض الرقابي والتعقيد من 1 إلى 5. تضيف المنصة أعلى خطر متبقٍ للإدارة والمدة منذ آخر تدقيق وآخر تقييم، وتحسب درجة الأولوية.', 'أنشئ خطة السنة. تظهر الجهات الأعلى أولوية أولاً؛ والمعلَّمة «مستحق» يجب تدقيقها هذا العام. أضف مهمة لكل منها برئيس فريق وتواريخ.', 'سجّل اعتماد لجنة التدقيق. تُقفل الخطة بعدها ويمكن بدء العمل الميداني.', 'لكل اختبار افتح ورقة عمل، وسجّل العينة والاستثناءات والاستنتاج، وأرفق الأدلة. يجب أن يراجعها مدقق آخر: لا أحد يراجع عمله بنفسه.', 'اكتب الملاحظات بالواقع والمعيار والسبب والأثر والتوصية. عند إصدار التقرير بتقييمه تذهب كل ملاحظة إلى المدير المسؤول عنها.', 'تابع كل ملاحظة: ترد الإدارة بإجراء وتاريخ، ثم تبلغ عن التنفيذ، ويتحقق المدقق قبل الإغلاق.'],
            'tips' => ['تبقى الملاحظات مسودات لا يراها إلا المدققون حتى يصدر التقرير.', 'تمديد التاريخ المستهدف يُحتسب ويُسجَّل، ويُحفظ التاريخ الأصلي.', 'تعرض النظرة العامة الملاحظات العالية المفتوحة والمتأخرة ونسبة ما أُغلق في موعده.']],
        'ia_findings' => ['title' => 'الرد على ملاحظات التدقيق', 'roles' => ['admin', 'risk_manager', 'compliance_officer', 'dept_manager', 'exec_viewer', 'auditor'], 'link' => '/ia/findings', 'summary' => 'ما الذي تفعله عندما يرفع التدقيق الداخلي ملاحظة على مجالك.',
            'steps' => ['تظهر الملاحظات الجديدة في «مهامي». لديك 14 يوماً للرد.', 'افتح الملاحظة واقرأ ما وُجد ولماذا يهم، ثم اكتب ردك والإجراء الذي تلتزم به وتاريخاً مستهدفاً واقعياً.', 'عند إنجاز العمل أبلغ عن التنفيذ، وصِف ما تم وأرفق الأدلة.', 'يفحص التدقيق الداخلي الأدلة ويغلق الملاحظة، أو يعيدها بملاحظة إن احتاجت المزيد.'],
            'tips' => ['لا يرد إلا المدير المسؤول المسمى في الملاحظة.', 'إن احتجت وقتاً أطول فاطلب ذلك من التدقيق الداخلي قبل التاريخ المستهدف ليسجل التاريخ الجديد.']],
        'aml' => ['title' => 'مكافحة غسل الأموال', 'roles' => ['admin', 'risk_manager', 'compliance_officer', 'exec_viewer', 'auditor'], 'link' => '/aml', 'summary' => 'تصنيف كل عميل حسب مخاطر غسل الأموال في أربعة أبعاد، ومتابعة العناية الواجبة والمراجعات، وتتبع تقارير غسل الأموال.',
            'steps' => ['راجع عوامل المخاطر أولاً: أنواع العملاء، والمنتجات والخدمات، وقنوات تقديم الخدمة، والدول، وكل منها منخفض أو متوسط أو مرتفع. القائمة المرفقة مثال فقط.', 'قيّم العميل باختيار نوعه ودولته ومنتجاته وقنواته، وضع علامة على «شخص معرّض سياسياً» أو «تطابق محتمل مع العقوبات» إن انطبق. يُحسب التصنيف ومستوى العناية الواجبة وموعد المراجعة القادمة.', 'تبين صفحة العميل كيف تم الوصول إلى التصنيف. لا يُعتمد تصنيف مختلف إلا بسبب مكتوب، ولا يقل أبداً عن مرتفع للشخص المعرّض سياسياً أو تطابق العقوبات.', 'سجّل المراجعات الدورية عند استحقاقها: المرتفع كل سنة، والمتوسط كل سنتين، والمنخفض كل ثلاث سنوات.', 'اربط ضوابط من مكتبة الضوابط بكل بُعد: نتائج اختبارها تخفض المخاطر المتبقية في النظرة العامة.', 'سجّل التقارير المرسلة إلى وحدة المعلومات المالية والجهة الرقابية بمواعيدها، وسجّل تاريخ إرسالها.'],
            'tips' => ['بلاغات المعاملات المشبوهة سرية: لا يطلع عليها إلا فريق مكافحة غسل الأموال.', 'يمكن تحميل العملاء من T24 بدلاً من إدخالهم يدوياً.', 'تغيير مستوى عامل يعيد تصنيف كل العملاء الذين يستخدمونه.']],
        't24' => ['title' => 'التكامل مع T24', 'roles' => ['admin'], 'link' => '/admin/integrations', 'summary' => 'تحميل العملاء وقيود الخسائر من النظام المصرفي الأساسي T24 عبر ملف أو واجهة برمجية.',
            'steps' => ['نزّل النماذج لتوضح لفريق T24 الأعمدة المطلوبة، وعدّل ربط الحقول بأسماء حقول T24 في المصرف.', 'حمّل ملف تصدير، أو أدخل عنوان الواجهة البرمجية وبيانات الدخول واختبر الاتصال وحمّل مباشرة.', 'يُفحص كل تحميل أولاً. إن كان أي سطر خاطئاً لا يُكتب شيء، ويعرض سجل التحميل الأخطاء حسب السطر.', 'جهّز المهمة المجدولة (bin/t24-sync.php) مع مسؤول الاستضافة للتحميل التلقائي كل ليلة.'],
            'tips' => ['تتحول رموز T24 إلى عوامل مخاطر غسل الأموال عبر حقل «رمز T24» في كل عامل.', 'إعادة تحميل فترة الخسائر نفسها تستبدلها، فلا يُحتسب شيء مرتين.', 'تُحفظ كلمة المرور أو الرمز مشفّرة ولا تُعرض مرة أخرى.']],
        'audit' => ['title' => 'سجل التدقيق', 'roles' => ['admin', 'auditor'], 'link' => '/audit', 'summary' => 'من فعل ماذا ومتى.',
